            self.exchanges
                .register_receiver(fragment_instance_id, expected_senders, params)?
                .into_iter()
                .collect(),
        ));
    }

    let translated = self.translate_fragment_logged(&params, dump_seq)?;
    self.execute_fragment(&params, translated)
}

